Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "Radial year clock of all TSS appointment requests with linked specialty strip plot and custom tooltip cards.",
  "signals": [
    {
      "name": "yr",
      "update": "length(data(''dataset'')) ? year(toDate(data(''dataset'')[0].datum)) : 2025"
    },
    {
      "name": "daysInYear",
      "update": "round((datetime(yr + 1, 0, 1) - datetime(yr, 0, 1)) / 864e5)"
    },
    {
      "name": "S",
      "update": "min(height, width * 0.56)"
    },
    {
      "name": "R",
      "update": "S / 2 - 24"
    },
    {
      "name": "cx",
      "update": "S / 2"
    },
    {
      "name": "cy",
      "update": "height / 2"
    },
    {
      "name": "rInner",
      "update": "R * 0.36"
    },
    {
      "name": "rOuter",
      "update": "R * 0.80"
    },
    {
      "name": "rLost",
      "update": "R * 0.87"
    },
    {
      "name": "rShare0",
      "update": "R * 0.93"
    },
    {
      "name": "rShare1",
      "update": "R * 1.0"
    },
    {
      "name": "panelX",
      "update": "S + 34"
    },
    {
      "name": "stripX0",
      "update": "panelX + 170"
    },
    {
      "name": "stripX1",
      "update": "width - 64"
    },
    {
      "name": "panelTop",
      "value": 52
    },
    {
      "name": "legendH",
      "value": 112
    },
    {
      "name": "rowsBottom",
      "update": "height - legendH - 16"
    },
    {
      "name": "nSpec",
      "update": "max(length(data(''specRank'')), 1)"
    },
    {
      "name": "rowH",
      "update": "(rowsBottom - panelTop) / nSpec"
    },
    {
      "name": "waitMax",
      "update": "max(42, ceil(((waitExt && waitExt[1]) || 0) / 7) * 7)"
    },
    {
      "name": "selSpec",
      "value": null,
      "on": [
        {
          "events": "@specHit:click",
          "update": "datum.arztgruppe === selSpec ? null : datum.arztgruppe"
        },
        {
          "events": "dblclick",
          "update": "null"
        }
      ]
    },
    {
      "name": "selUrg",
      "value": null,
      "on": [
        {
          "events": "@urgHit:click",
          "update": "datum.u === selUrg ? null : datum.u"
        },
        {
          "events": "dblclick",
          "update": "null"
        }
      ]
    },
    {
      "name": "ptr",
      "value": [
        -9999,
        -9999
      ],
      "on": [
        {
          "events": "mousemove",
          "update": "xy()"
        },
        {
          "events": "touchmove",
          "update": "xy()"
        },
        {
          "events": {
            "source": "window",
            "type": "mouseout",
            "filter": "!event.relatedTarget"
          },
          "update": "[-9999, -9999]"
        },
        {
          "events": {
            "source": "view",
            "type": "mouseout",
            "filter": [
              "event.type === ''mouseout''",
              "!event.relatedTarget || (!event.relatedTarget.ownerSVGElement && event.relatedTarget.tagName !== ''svg'')"
            ]
          },
          "update": "[-9999, -9999]"
        }
      ]
    },
    {
      "name": "ptrDx",
      "update": "ptr[0] - cx"
    },
    {
      "name": "ptrDy",
      "update": "cy - ptr[1]"
    },
    {
      "name": "ptrR",
      "update": "sqrt(ptrDx * ptrDx + ptrDy * ptrDy)"
    },
    {
      "name": "ptrTheta",
      "update": "atan2(ptrDx, ptrDy) < 0 ? atan2(ptrDx, ptrDy) + 2 * PI : atan2(ptrDx, ptrDy)"
    },
    {
      "name": "hoverReq",
      "update": "length(data(''hoverHit'')) ? {d: data(''hoverHit'')[0], x: ptr[0], y: ptr[1]} : null"
    },
    {
      "name": "hoverMonth",
      "update": "ptrR >= rShare0 - 2 && ptrR <= rShare1 + 2 && length(data(''months'')) === 12 ? {d: data(''months'')[month(datetime(yr, 0, 1 + floor(ptrTheta / (2 * PI) * daysInYear)))], x: ptr[0], y: ptr[1]} : null"
    },
    {
      "name": "cardReq",
      "value": null,
      "on": [
        {
          "events": {
            "signal": "hoverReq"
          },
          "update": "hoverReq ? hoverReq : cardReq"
        }
      ]
    },
    {
      "name": "cardMonth",
      "value": null,
      "on": [
        {
          "events": {
            "signal": "hoverMonth"
          },
          "update": "hoverMonth && isValid(hoverMonth.d.n) ? hoverMonth : cardMonth"
        }
      ]
    },
    {
      "name": "sumRow",
      "update": "length(data(''summary'')) ? data(''summary'')[0] : {n: 0, placed: 0, within: 0, med: null}"
    }
  ],
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "base",
      "source": "dataset",
      "transform": [
        {
          "type": "formula",
          "as": "d",
          "expr": "toDate(datum.datum)"
        },
        {
          "type": "formula",
          "as": "doy",
          "expr": "round((datetime(year(datum.d), month(datum.d), date(datum.d)) - datetime(year(datum.d), 0, 1)) / 864e5)"
        },
        {
          "type": "formula",
          "as": "m",
          "expr": "month(datum.d)"
        },
        {
          "type": "formula",
          "as": "wait",
          "expr": "isValid(datum.wartezeit_tage) && datum.wartezeit_tage !== '''' ? +datum.wartezeit_tage : null"
        },
        {
          "type": "formula",
          "as": "placed",
          "expr": "datum.status === ''VERMITTELT''"
        },
        {
          "type": "formula",
          "as": "attended",
          "expr": "datum.termin_wahrgenommen === true || datum.termin_wahrgenommen === 1 || datum.termin_wahrgenommen === ''True''"
        },
        {
          "type": "formula",
          "as": "waitPlaced",
          "expr": "datum.placed ? datum.wait : null"
        },
        {
          "type": "formula",
          "as": "within",
          "expr": "datum.placed && datum.wait <= 28 ? 1 : 0"
        },
        {
          "type": "formula",
          "as": "placedN",
          "expr": "datum.placed ? 1 : 0"
        },
        {
          "type": "formula",
          "as": "jit",
          "expr": "((datum.anfrage_id * 7919) % 101) / 100 - 0.5"
        },
        {
          "type": "formula",
          "as": "jit2",
          "expr": "((datum.anfrage_id * 104729) % 97) / 96 - 0.5"
        },
        {
          "type": "formula",
          "as": "theta",
          "expr": "2 * PI * (datum.doy + 0.5 + datum.jit * 0.9) / daysInYear"
        },
        {
          "type": "extent",
          "field": "waitPlaced",
          "signal": "waitExt"
        }
      ]
    },
    {
      "name": "specRank",
      "source": "base",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "arztgruppe"
          ],
          "fields": [
            "waitPlaced"
          ],
          "ops": [
            "median"
          ],
          "as": [
            "medAll"
          ]
        },
        {
          "type": "window",
          "sort": {
            "field": [
              "medAll",
              "arztgruppe"
            ],
            "order": [
              "descending",
              "ascending"
            ]
          },
          "ops": [
            "row_number"
          ],
          "as": [
            "rank"
          ]
        }
      ]
    },
    {
      "name": "requests",
      "source": "base",
      "transform": [
        {
          "type": "lookup",
          "from": "specRank",
          "key": "arztgruppe",
          "fields": [
            "arztgruppe"
          ],
          "values": [
            "medAll",
            "rank"
          ],
          "as": [
            "specMed",
            "rank"
          ]
        },
        {
          "type": "formula",
          "as": "inFocus",
          "expr": "(!selSpec || datum.arztgruppe === selSpec) && (!selUrg || datum.dringlichkeit === selUrg)"
        }
      ]
    },
    {
      "name": "pos",
      "source": "requests",
      "transform": [
        {
          "type": "formula",
          "as": "rad",
          "expr": "datum.placed ? rInner + (rOuter - rInner) * datum.wait / waitMax : rLost + (datum.status === ''STORNIERT'' ? -4 : 4)"
        },
        {
          "type": "formula",
          "as": "px",
          "expr": "cx + datum.rad * sin(datum.theta)"
        },
        {
          "type": "formula",
          "as": "py",
          "expr": "cy - datum.rad * cos(datum.theta)"
        }
      ]
    },
    {
      "name": "hoverHit",
      "source": "pos",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.inFocus"
        },
        {
          "type": "formula",
          "as": "dist2",
          "expr": "pow(datum.px - ptr[0], 2) + pow(datum.py - ptr[1], 2)"
        },
        {
          "type": "filter",
          "expr": "datum.dist2 <= 64"
        },
        {
          "type": "collect",
          "sort": {
            "field": "dist2"
          }
        }
      ]
    },
    {
      "name": "focus",
      "source": "requests",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.inFocus"
        }
      ]
    },
    {
      "name": "summary",
      "source": "focus",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "placedN",
            "placedN",
            "within",
            "waitPlaced"
          ],
          "ops": [
            "count",
            "sum",
            "sum",
            "median"
          ],
          "as": [
            "n",
            "placed",
            "within",
            "med"
          ]
        }
      ]
    },
    {
      "name": "monthly",
      "source": "focus",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "m"
          ],
          "fields": [
            "placedN",
            "placedN",
            "within",
            "waitPlaced"
          ],
          "ops": [
            "count",
            "sum",
            "sum",
            "median"
          ],
          "as": [
            "n",
            "placed",
            "within",
            "med"
          ]
        },
        {
          "type": "formula",
          "as": "share",
          "expr": "datum.placed ? datum.within / datum.placed : null"
        },
        {
          "type": "formula",
          "as": "thetaMid",
          "expr": "2 * PI * ((datetime(yr, datum.m, 15) - datetime(yr, 0, 1)) / 864e5) / daysInYear"
        },
        {
          "type": "collect",
          "sort": {
            "field": "m"
          }
        }
      ]
    },
    {
      "name": "medianLine",
      "source": "monthly",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum.med)"
        }
      ]
    },
    {
      "name": "months",
      "transform": [
        {
          "type": "sequence",
          "start": 0,
          "stop": 12,
          "as": "m"
        },
        {
          "type": "formula",
          "as": "t0",
          "expr": "2 * PI * ((datetime(yr, datum.m, 1) - datetime(yr, 0, 1)) / 864e5) / daysInYear"
        },
        {
          "type": "formula",
          "as": "t1",
          "expr": "2 * PI * ((datetime(yr, datum.m + 1, 1) - datetime(yr, 0, 1)) / 864e5) / daysInYear"
        },
        {
          "type": "formula",
          "as": "mid",
          "expr": "(datum.t0 + datum.t1) / 2"
        },
        {
          "type": "formula",
          "as": "label",
          "expr": "timeFormat(datetime(yr, datum.m, 1), ''%b'')"
        },
        {
          "type": "formula",
          "as": "longLabel",
          "expr": "timeFormat(datetime(yr, datum.m, 1), ''%B %Y'')"
        },
        {
          "type": "lookup",
          "from": "monthly",
          "key": "m",
          "fields": [
            "m"
          ],
          "values": [
            "n",
            "placed",
            "within",
            "med",
            "share"
          ]
        }
      ]
    },
    {
      "name": "urgFocus",
      "source": "requests",
      "transform": [
        {
          "type": "filter",
          "expr": "!selUrg || datum.dringlichkeit === selUrg"
        }
      ]
    },
    {
      "name": "specStats",
      "source": "urgFocus",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "arztgruppe"
          ],
          "fields": [
            "placedN",
            "placedN",
            "within",
            "waitPlaced"
          ],
          "ops": [
            "count",
            "sum",
            "sum",
            "median"
          ],
          "as": [
            "n",
            "placed",
            "within",
            "med"
          ]
        }
      ]
    },
    {
      "name": "specRows",
      "source": "specRank",
      "transform": [
        {
          "type": "lookup",
          "from": "specStats",
          "key": "arztgruppe",
          "fields": [
            "arztgruppe"
          ],
          "values": [
            "n",
            "placed",
            "within",
            "med"
          ]
        },
        {
          "type": "formula",
          "as": "share",
          "expr": "datum.placed ? datum.within / datum.placed : null"
        },
        {
          "type": "formula",
          "as": "yc",
          "expr": "panelTop + (datum.rank - 0.5) * rowH"
        }
      ]
    },
    {
      "name": "stripDots",
      "source": "urgFocus",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.placed"
        }
      ]
    },
    {
      "name": "rings",
      "values": [
        {
          "v": 14
        },
        {
          "v": 28
        },
        {
          "v": 42
        },
        {
          "v": 56
        }
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "datum.v < waitMax"
        }
      ]
    },
    {
      "name": "urgencies",
      "values": [
        {
          "u": "AKUT",
          "label": "Acute",
          "i": 0
        },
        {
          "u": "DRINGEND",
          "label": "Urgent",
          "i": 1
        },
        {
          "u": "ROUTINE",
          "label": "Routine",
          "i": 2
        }
      ]
    },
    {
      "name": "outcomes",
      "values": [
        {
          "k": "att",
          "label": "Attended",
          "i": 0
        },
        {
          "k": "noshow",
          "label": "No-show",
          "i": 1
        },
        {
          "k": "cancel",
          "label": "Cancelled",
          "i": 2
        },
        {
          "k": "none",
          "label": "Not placed",
          "i": 3
        }
      ]
    },
    {
      "name": "shareKey",
      "values": [
        {
          "s": 0.7,
          "label": "≤ 70 %",
          "i": 0
        },
        {
          "s": 0.8,
          "label": "80 %",
          "i": 1
        },
        {
          "s": 0.9,
          "label": "≥ 90 %",
          "i": 2
        }
      ]
    },
    {
      "name": "hoverReqLive",
      "values": [
        {}
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "hoverReq != null"
        }
      ]
    },
    {
      "name": "hoverReqRow",
      "values": [
        {}
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "cardReq != null"
        }
      ]
    },
    {
      "name": "hoverMonthRow",
      "values": [
        {}
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "cardMonth != null"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "r",
      "type": "linear",
      "zero": true,
      "nice": false,
      "domain": {
        "signal": "[0, waitMax]"
      },
      "range": {
        "signal": "[rInner, rOuter]"
      }
    },
    {
      "name": "strip",
      "type": "linear",
      "zero": true,
      "nice": false,
      "domain": {
        "signal": "[0, waitMax]"
      },
      "range": {
        "signal": "[stripX0, stripX1]"
      }
    },
    {
      "name": "urg",
      "type": "ordinal",
      "domain": [
        "AKUT",
        "DRINGEND",
        "ROUTINE"
      ],
      "range": [
        "#e34948",
        "#eda100",
        "#2a78d6"
      ]
    },
    {
      "name": "share",
      "type": "linear",
      "domain": [
        0.7,
        0.8,
        0.9
      ],
      "range": [
        "#e34948",
        "#dcdad2",
        "#2a78d6"
      ],
      "clamp": true,
      "interpolate": "rgb"
    }
  ],
  "marks": [
    {
      "type": "rect",
      "name": "pointerCatcher",
      "interactive": true,
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "y": {
            "value": 0
          },
          "width": {
            "signal": "width"
          },
          "height": {
            "signal": "height"
          },
          "fill": {
            "value": "#ffffff"
          },
          "fillOpacity": {
            "value": 0.001
          }
        }
      }
    },
    {
      "type": "arc",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "cy"
          },
          "innerRadius": {
            "signal": "rInner"
          },
          "outerRadius": {
            "signal": "rLost + 10"
          },
          "startAngle": {
            "value": 0
          },
          "endAngle": {
            "signal": "2 * PI"
          },
          "fill": {
            "value": "#f7f6f2"
          }
        }
      }
    },
    {
      "type": "arc",
      "interactive": false,
      "from": {
        "data": "months"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "cy"
          },
          "innerRadius": {
            "signal": "rInner"
          },
          "outerRadius": {
            "signal": "rLost + 10"
          },
          "startAngle": {
            "signal": "datum.t0"
          },
          "endAngle": {
            "signal": "datum.t1"
          },
          "fill": {
            "signal": "datum.m % 2 ? ''#f0efea'' : ''#f7f6f2''"
          }
        }
      }
    },
    {
      "type": "arc",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "cy"
          },
          "innerRadius": {
            "signal": "scale(''r'', 28)"
          },
          "outerRadius": {
            "signal": "rOuter + 4"
          },
          "startAngle": {
            "value": 0
          },
          "endAngle": {
            "signal": "2 * PI"
          },
          "fill": {
            "value": "#e34948"
          },
          "fillOpacity": {
            "value": 0.06
          }
        }
      }
    },
    {
      "type": "rule",
      "interactive": false,
      "from": {
        "data": "months"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx + rInner * sin(datum.t0)"
          },
          "y": {
            "signal": "cy - rInner * cos(datum.t0)"
          },
          "x2": {
            "signal": "cx + (rLost + 10) * sin(datum.t0)"
          },
          "y2": {
            "signal": "cy - (rLost + 10) * cos(datum.t0)"
          },
          "stroke": {
            "value": "#ffffff"
          },
          "strokeWidth": {
            "value": 2
          }
        }
      }
    },
    {
      "type": "symbol",
      "interactive": false,
      "from": {
        "data": "rings"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "cy"
          },
          "shape": {
            "value": "circle"
          },
          "size": {
            "signal": "PI * pow(scale(''r'', datum.v), 2) * 4 / PI"
          },
          "fill": {
            "value": "transparent"
          },
          "stroke": {
            "signal": "datum.v === 28 ? ''#e34948'' : ''#d4d2c9''"
          },
          "strokeWidth": {
            "signal": "datum.v === 28 ? 1.6 : 0.8"
          },
          "strokeDash": {
            "signal": "datum.v === 28 ? [6, 4] : [2, 3]"
          }
        }
      }
    },
    {
      "type": "arc",
      "name": "shareArcs",
      "from": {
        "data": "months"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "cy"
          },
          "innerRadius": {
            "signal": "rShare0"
          },
          "outerRadius": {
            "signal": "rShare1"
          },
          "startAngle": {
            "signal": "datum.t0 + 0.008"
          },
          "endAngle": {
            "signal": "datum.t1 - 0.008"
          },
          "cornerRadius": {
            "value": 2
          },
          "fill": {
            "signal": "isValid(datum.share) ? scale(''share'', datum.share) : ''#e1e0d9''"
          },
          "stroke": {
            "signal": "hoverMonth && hoverMonth.d.m === datum.m ? ''#0b0b0b'' : null"
          },
          "strokeWidth": {
            "value": 1.5
          }
        }
      }
    },
    {
      "type": "text",
      "name": "monthLabel",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
